import{_ as a,o as s,c as e,ag as p}from"./chunks/framework.DUTPmUpA.js";const u=JSON.parse('{"title":"Создание врожденных (доступно с 1 уровня) способностей.","description":"","frontmatter":{"title":"Создание врожденных (доступно с 1 уровня) способностей.","author":"DoctorGester","steamId":"76561198046920629","date":"27.09.2019"},"headers":[],"relativePath":"abilities/creating-innate-abilities.md","filePath":"abilities/creating-innate-abilities.md"}'),i={name:"abilities/creating-innate-abilities.md"};function l(t,n,c,r,d,o){return s(),e("div",null,[...n[0]||(n[0]=[p(`<p>здание врожденных (доступно с 1 уровня) способностей.</p><p>Эта статья поможет вам создать способность, которая сразу же будет доступна данному герою, например, Stone Remnant Earth Spirit. В этом руководстве предполагается, что у вас уже есть способность, настроенная для героя.</p><h2 id="способности-lua" tabindex="-1">Способности Lua <a class="header-anchor" href="#способности-lua" aria-label="Permalink to &quot;Способности Lua&quot;">​</a></h2><p>Способности Lua могут определять метод <code>Spawn</code>, который вызывается движком при создании способности.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>my_innate_ability = my_innate_ability or {}</span></span>
<span class="line"><span>function my_innate_ability:Spawn()</span></span>
<span class="line"><span>    if IsServer() then</span></span>
<span class="line"><span>        self:SetLevel(1)</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="управляемые-данными-и-встроенные-возможности" tabindex="-1">Управляемые данными и встроенные возможности <a class="header-anchor" href="#управляемые-данными-и-встроенные-возможности" aria-label="Permalink to &quot;Управляемые данными и встроенные возможности&quot;">​</a></h2><p>План таков:</p><ol><li>Подпишитесь на событие появления героя.</li><li>Определите, есть ли у появившегося героя особая способность.</li><li>Повышайте уровень</li></ol><p>Хорошо. Поскольку точкой входа в каждый мод является файл <code>addon_game_mode.lua</code>, перейдите туда и найдите <code>function Activate()</code>. Активация — это функция, вызываемая в самом начале нашей пользовательской игры, когда все игроки загрузились. Мы можем подписаться на события, используя <code>ListenToGameEvent</code>.</p><p>Поместите следующий код в функцию <code>Activate</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>ListenToGameEvent(&#39;npc_spawned&#39;, function(event)</span></span>
<span class="line"><span>    HandleNpcSpawned(event.entindex)</span></span>
<span class="line"><span>end, nil)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Этот код подписывается на событие <code>npc_spawned</code>, а затем вызывает функцию HandleNpcSpawned (мы создадим ее позже) с порожденным индексом сущности. Этот индекс сущности предоставляется нам в таблице событий при запуске события.</p><p>Давайте создадим функцию <code>HandleNpcSpawned</code>, поместим ее в тот же файл чуть ниже <code>Activate</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function HandleNpcSpawned(entityIndex)</span></span>
<span class="line"><span>    local entity = EntIndexToHScript(entityIndex)</span></span>
<span class="line"><span>    local innateAbilityName = &quot;my_innate_ability&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if entity:IsRealHero() and entity:HasAbility(innateAbilityName) then</span></span>
<span class="line"><span>        entity:FindAbilityByName(innateAbilityName):SetLevel(1)</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Давайте пройдемся здесь построчно. После определения функции, которая принимает наш параметр objectIndex, мы определяем переменную, которая содержит фактическую сущность. Мы превращаем индекс объекта в реальный объект, используя <code>EntIndexToHScript</code>. Теперь мы можем вызывать методы нашей реальной сущности. Сначала мы объявляем имя нашей врожденной способности, чтобы ее было проще использовать. Затем мы создаем условие, в котором проверяем, что наша сущность действительно является героем и обладает такой способностью. Если все условия выполняются, мы получаем дескриптор этой способности и сразу же устанавливаем для нее уровень 1.</p><p>Вот и все! Теперь все герои, у которых есть <code>my_innate_ability</code>, будут автоматически повышать его уровень при появлении.</p>`,16)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
